    let dir = corpus_root().join("raw");
    let mut seen = 0;
    for name in [
        "cr2-canon-40d.cr2",
        "cr2-canon-550d.cr2",
        "cr2-canon-5d2.cr2",
        "cr2-canon-5d3.cr2",
        "cr2-canon-5dsr.cr2",
        "cr2-canon-6d.cr2",
        "cr2-canon-7d.cr2",
        "cr2-canon-80d.cr2",
    ] {
