        ("srw-samsung-ex1.srw", 14, (3648, 2736), (3648, 2736), "RGGB", true),
    ];
    let mut seen = 0;
    for (name, bits, active, crop, cfa, whole) in cases {
        let Ok(bytes) = std::fs::read(dir.join(name)) else {
